// Realistic demo dataset — fictional clients only, no real persons/companies.
// Populates every Module 4 screen (dashboard, KYC queues, CRA, transactions,
// alerts, investigations, STR, reports) with data generated by actually
// running the app's own engines (assessRisk/assessCorporateRisk, CRA
// banding, screening-rule evaluation) against hand-authored profiles —
// never hand-picked scores — so every number on screen is internally
// consistent with what the app would compute for a real case.
//
// Guarded by the `demoDataSeeded` SystemSetting flag in seed.ts: this only
// ever ADDS rows (case numbers/txn refs/etc. continue the same counters
// real usage relies on) and never deletes or touches existing data, so it's
// safe to run against a DB that already has real user-created cases.

import type { PrismaClient } from '@prisma/client';
import { encryptField } from '../../src/lib/crypto';
import {
  assessRisk,
  assessCorporateRisk,
  type RiskInput,
  type CorporateRiskInput,
  type CountryExposure,
} from '../../src/lib/risk/engine';
import { craBandFromScore, nextCraReviewDate } from '../../src/lib/risk/cra';
import { evaluateRule, DEFAULT_ALERT_TYPE, type RuleParams, type TxnLike } from '../../src/lib/transactions/rules';
import type {
  CaseStatus,
  EmploymentStatus,
  IncomeSource,
  PepPosition,
  FatfStatus,
  TransactionType,
} from '../../src/lib/constants';

type EvaluableRuleType = 'VELOCITY_COUNT_SUM' | 'LARGE_SINGLE_TRANSACTION' | 'HIGH_RISK_COUNTRY';

const DAY_MS = 24 * 60 * 60 * 1000;
const daysAgo = (n: number, hour = 10) => {
  const d = new Date(Date.now() - n * DAY_MS);
  d.setHours(hour, 0, 0, 0);
  return d;
};
const hoursAfter = (d: Date, h: number) => new Date(d.getTime() + h * 60 * 60 * 1000);
const daysAfter = (d: Date, n: number) => new Date(d.getTime() + n * DAY_MS);

// ---------- counters (mirrors src/lib/cases/actions.ts, transactions/actions.ts, etc.) ----------

async function nextCaseNumber(prisma: PrismaClient): Promise<string> {
  const year = new Date().getFullYear();
  const counter = await prisma.caseCounter.upsert({
    where: { year },
    create: { year, counter: 1 },
    update: { counter: { increment: 1 } },
  });
  return `KYC-${year}-${String(counter.counter).padStart(5, '0')}`;
}

async function nextTxnRef(prisma: PrismaClient): Promise<string> {
  const year = new Date().getFullYear();
  const counter = await prisma.transactionCounter.upsert({
    where: { year },
    create: { year, counter: 1 },
    update: { counter: { increment: 1 } },
  });
  return `TXN-${year}-${String(counter.counter).padStart(6, '0')}`;
}

async function nextInvestigationRef(prisma: PrismaClient): Promise<string> {
  const year = new Date().getFullYear();
  const counter = await prisma.investigationCounter.upsert({
    where: { year },
    create: { year, counter: 1 },
    update: { counter: { increment: 1 } },
  });
  return `INV-${year}-${String(counter.counter).padStart(5, '0')}`;
}

async function nextStrRef(prisma: PrismaClient): Promise<string> {
  const year = new Date().getFullYear();
  const counter = await prisma.strCounter.upsert({
    where: { year },
    create: { year, counter: 1 },
    update: { counter: { increment: 1 } },
  });
  return `STR-${year}-${String(counter.counter).padStart(5, '0')}`;
}

async function logAudit(
  prisma: PrismaClient,
  entry: {
    action: string;
    caseId?: string | null;
    actorId?: string | null;
    fromStatus?: string | null;
    toStatus?: string | null;
    details?: Record<string, unknown>;
    createdAt: Date;
  },
): Promise<void> {
  await prisma.auditLog.create({
    data: {
      action: entry.action,
      caseId: entry.caseId ?? null,
      actorId: entry.actorId ?? null,
      fromStatus: entry.fromStatus ?? null,
      toStatus: entry.toStatus ?? null,
      detailsJson: entry.details ? JSON.stringify(entry.details) : null,
      createdAt: entry.createdAt,
    },
  });
}

function countryExposure(
  countryCode: string,
  fatfByCode: Map<string, FatfStatus>,
  domesticCode = 'KW',
): CountryExposure[] {
  const fatfStatus = fatfByCode.get(countryCode) ?? 'NONE';
  if (fatfStatus === 'NONE') return [];
  return [{ field: 'nationality', countryCode, fatfStatus, domesticExempt: fatfStatus === 'GREY' && countryCode === domesticCode }];
}

