export async function seedDemoData(prisma: PrismaClient): Promise<void> {
  const [employee, compliance, manager] = await Promise.all([
    prisma.user.findUniqueOrThrow({ where: { email: 'employee@aml.local' } }),
    prisma.user.findUniqueOrThrow({ where: { email: 'compliance@aml.local' } }),
    prisma.user.findUniqueOrThrow({ where: { email: 'manager@aml.local' } }),
  ]);

  const countries = await prisma.country.findMany({ select: { code: true, fatfStatus: true } });
  const fatfByCode = new Map(countries.map((c) => [c.code, c.fatfStatus as FatfStatus]));

  // ---------- individual KYC cases ----------

  type ApprovedCase = { id: string; nameEn: string; type: 'INDIVIDUAL' | 'CORPORATE'; storyRole?: string };
  const approvedCases: ApprovedCase[] = [];

  for (const spec of INDIVIDUALS) {
    const caseNumber = await nextCaseNumber(prisma);
    const createdAt = daysAgo(spec.createdDaysAgo);
    const exposures = countryExposure(spec.nationality, fatfByCode);

    const riskInput: RiskInput = {
      countryExposures: exposures,
      isPep: spec.isPep,
      hasPepRelative: spec.hasPepRelative,
      isManagedByOther: spec.isManagedByOther,
      employmentStatus: spec.employmentStatus,
      sourcesOfIncome: spec.sourcesOfIncome,
      annualIncomeKd: spec.annualIncomeKd,
      approxWealthKd: spec.approxWealthKd,
      isRelatedParty: spec.isRelatedParty,
      hasControl: spec.hasControl,
      isBoardMember: spec.isBoardMember,
    };
    const risk = assessRisk(riskInput);

    const isDraft = spec.status === 'DRAFT';
    const submittedAt = isDraft ? null : hoursAfter(createdAt, 4);
    const isEscalated = spec.status === 'PENDING_MANAGER' || (spec.status === 'APPROVED' && risk.rating === 'HIGH');
    const complianceAt = submittedAt ? daysAfter(submittedAt, 1) : null;
    const managerAt =
      spec.status === 'APPROVED' && isEscalated ? daysAfter(complianceAt ?? createdAt, 2) : null;

    const complianceDecision = isDraft
      ? null
      : spec.status === 'RETURNED'
        ? 'RETURNED'
        : spec.status === 'REJECTED'
          ? 'REJECTED'
          : isEscalated
            ? 'ESCALATED'
            : 'APPROVED';

    const kase = await prisma.kycCase.create({
      data: {
        caseNumber,
        clientType: 'INDIVIDUAL',
        formType: 'NEW_CLIENT',
        status: spec.status,
        makerId: employee.id,
        checkerId: isDraft ? null : compliance.id,
        approverId: managerAt ? manager.id : null,
        systemRiskScore: risk.score,
        systemRiskRating: risk.rating,
        riskFactorsJson: JSON.stringify(risk.factors),
        finalRiskRating: risk.rating,
        submittedAt,
        complianceDecision,
        complianceNotes: spec.status === 'RETURNED' ? 'Please provide an updated salary certificate and source-of-funds explanation.' : null,
        complianceAt,
        managerDecision: managerAt ? 'APPROVED' : null,
        managerNotes: managerAt ? 'Reviewed escalation — approved with standard ongoing monitoring.' : null,
        managerAt,
        createdAt,
      },
    });

    await prisma.kycProfile.create({
      data: {
        caseId: kase.id,
        title: spec.title,
        fullName: spec.nameEn,
        dobEnc: encryptField('1985-06-15'),
        nationality: spec.nationality,
        residenceCountry: 'KW',
        residenceCity: 'Kuwait City',
        civilIdNoEnc: encryptField(spec.civilId),
        civilIdExpiry: daysAfter(new Date(), 700),
        mobileEnc: encryptField(spec.mobile),
        emailEnc: encryptField(spec.email),
        employmentStatus: spec.employmentStatus,
        employer: spec.employer || null,
        jobTitle: spec.jobTitle || null,
        sourcesOfIncomeJson: JSON.stringify(spec.sourcesOfIncome),
        annualIncomeKd: spec.annualIncomeKd,
        approxWealthKd: spec.approxWealthKd,
        isManagedByOther: spec.isManagedByOther,
        managerType: spec.isManagedByOther ? 'POA' : null,
        isPep: spec.isPep,
        pepPositionsJson: spec.pepPositions ? JSON.stringify(spec.pepPositions) : null,
        hasPepRelative: spec.hasPepRelative,
        pepName: spec.hasPepRelative ? 'Family relative (senior public office)' : null,
        pepRelationship: spec.hasPepRelative ? 'PARENT' : null,
        isRelatedParty: spec.isRelatedParty,
        hasControl: spec.hasControl,
        isBoardMember: spec.isBoardMember,
        declarationAccepted: !isDraft,
      },
    });

    await logAudit(prisma, { action: 'CASE_CREATED', caseId: kase.id, actorId: employee.id, createdAt });
    if (submittedAt) {
      await logAudit(prisma, {
        action: 'CASE_SUBMITTED', caseId: kase.id, actorId: employee.id,
        fromStatus: 'DRAFT', toStatus: 'PENDING_COMPLIANCE', createdAt: submittedAt,
      });
    }
    if (complianceAt) {
      const action =
        spec.status === 'RETURNED' ? 'COMPLIANCE_RETURNED' : spec.status === 'REJECTED' ? 'COMPLIANCE_REJECTED' : isEscalated ? 'COMPLIANCE_ESCALATED' : 'COMPLIANCE_APPROVED';
      await logAudit(prisma, {
        action, caseId: kase.id, actorId: compliance.id,
        fromStatus: 'PENDING_COMPLIANCE', toStatus: spec.status === 'APPROVED' && isEscalated ? 'PENDING_MANAGER' : spec.status,
        createdAt: complianceAt,
      });
    }
    if (managerAt) {
      await logAudit(prisma, {
        action: 'MANAGER_APPROVED', caseId: kase.id, actorId: manager.id,
        fromStatus: 'PENDING_MANAGER', toStatus: 'APPROVED', createdAt: managerAt,
      });
    }

    if (spec.status === 'APPROVED') {
      approvedCases.push({ id: kase.id, nameEn: spec.nameEn, type: 'INDIVIDUAL' });
      if (spec.craEligible) {
        const band = craBandFromScore(risk.score);
        const assessedAt = daysAgo(Math.max(1, spec.createdDaysAgo - 10));
        await prisma.kycCase.update({
          where: { id: kase.id },
          data: {
            craScore: risk.score,
            craBand: band,
            craLastAssessedAt: assessedAt,
            craNextReviewAt: nextCraReviewDate(band, assessedAt),
          },
        });
      }
    }
  }

  // ---------- corporate KYC cases ----------

  for (const spec of CORPORATES) {
    const caseNumber = await nextCaseNumber(prisma);
    const createdAt = daysAgo(spec.createdDaysAgo);

    const riskInput: CorporateRiskInput = {
      countryExposures: [],
      hasFatfDealings: spec.hasFatfDealings,
      activityHighRisk: spec.activityHighRisk,
      isPep: spec.isPep,
      isRegulatedEntity: spec.isRegulatedEntity,
      activityIncludesSecurities: spec.activityIncludesSecurities,
      isDirectorOrMajorShareholderOfListed: spec.isDirectorOrMajorShareholderOfListed,
      hasSignificantShareholding: spec.hasSignificantShareholding,
      isRelatedParty: spec.isRelatedParty,
      annualTurnoverKd: spec.annualTurnoverKd,
      approxWealthKd: spec.approxWealthKd,
    };
    const risk = assessCorporateRisk(riskInput);

    const isDraft = spec.status === 'DRAFT';
    const submittedAt = isDraft ? null : hoursAfter(createdAt, 6);
    const isEscalated = spec.status === 'PENDING_MANAGER' || (spec.status === 'APPROVED' && risk.rating === 'HIGH');
    const complianceAt = submittedAt ? daysAfter(submittedAt, 1) : null;
    const managerAt = spec.status === 'APPROVED' && isEscalated ? daysAfter(complianceAt ?? createdAt, 2) : null;

    const complianceDecision = isDraft ? null : isEscalated ? 'ESCALATED' : 'APPROVED';

    const kase = await prisma.kycCase.create({
      data: {
        caseNumber,
        clientType: 'CORPORATE',
        formType: 'NEW_CLIENT',
        status: spec.status,
        makerId: employee.id,
        checkerId: isDraft ? null : compliance.id,
        approverId: managerAt ? manager.id : null,
        systemRiskScore: risk.score,
        systemRiskRating: risk.rating,
        riskFactorsJson: JSON.stringify(risk.factors),
        finalRiskRating: risk.rating,
        submittedAt,
        complianceDecision,
        complianceAt,
        managerDecision: managerAt ? 'APPROVED' : null,
        managerNotes: managerAt ? 'Escalation reviewed — approved with enhanced ongoing monitoring.' : null,
        managerAt,
        createdAt,
      },
    });

    await prisma.corporateProfile.create({
      data: {
        caseId: kase.id,
        companyType: 'LIMITED_PARTNERSHIP',
        legalName: spec.legalName,
        incorporationDate: daysAgo(3650),
        mainActivities: spec.mainActivities,
        registrationNo: spec.registrationNo,
        incorporationCountry: 'KW',
        registeredAddress: 'Kuwait City, Kuwait',
        taxResidenceCountry: 'KW',
        licenseNumber: spec.registrationNo,
        activityHighRisk: spec.activityHighRisk,
        hasFatfDealings: spec.hasFatfDealings,
        isRegulatedEntity: spec.isRegulatedEntity,
        activityIncludesSecurities: spec.activityIncludesSecurities,
        isDirectorOrMajorShareholderOfListed: spec.isDirectorOrMajorShareholderOfListed,
        hasSignificantShareholding: spec.hasSignificantShareholding,
        isRelatedParty: spec.isRelatedParty,
        annualTurnoverKd: spec.annualTurnoverKd,
        approxWealthKd: spec.approxWealthKd,
        isPep: spec.isPep,
        bank1Name: 'National Bank of Kuwait', bank1Country: 'KW', bank1Currency: 'KWD',
        declarationAccepted: !isDraft,
        authorizedSignatoryName: `${spec.legalName} — Authorized Signatory`,
      },
    });

    await logAudit(prisma, { action: 'CASE_CREATED', caseId: kase.id, actorId: employee.id, createdAt });
    if (submittedAt) {
      await logAudit(prisma, {
        action: 'CASE_SUBMITTED', caseId: kase.id, actorId: employee.id,
        fromStatus: 'DRAFT', toStatus: 'PENDING_COMPLIANCE', createdAt: submittedAt,
      });
    }
    if (complianceAt) {
      const action = isEscalated ? 'COMPLIANCE_ESCALATED' : 'COMPLIANCE_APPROVED';
      await logAudit(prisma, {
        action, caseId: kase.id, actorId: compliance.id,
        fromStatus: 'PENDING_COMPLIANCE', toStatus: spec.status === 'APPROVED' && isEscalated ? 'PENDING_MANAGER' : spec.status,
        createdAt: complianceAt,
      });
    }
    if (managerAt) {
      await logAudit(prisma, {
        action: 'MANAGER_APPROVED', caseId: kase.id, actorId: manager.id,
        fromStatus: 'PENDING_MANAGER', toStatus: 'APPROVED', createdAt: managerAt,
      });
    }

    if (spec.status === 'APPROVED') {
      approvedCases.push({ id: kase.id, nameEn: spec.legalName, type: 'CORPORATE' });
      if (spec.craEligible) {
        const band = craBandFromScore(risk.score);
        const assessedAt = daysAgo(Math.max(1, spec.createdDaysAgo - 10));
        await prisma.kycCase.update({
          where: { id: kase.id },
          data: {
            craScore: risk.score,
            craBand: band,
            craLastAssessedAt: assessedAt,
            craNextReviewAt: nextCraReviewDate(band, assessedAt),
          },
        });
      }
    }
  }

  // ---------- screening rules ----------

  const ruleDefs: { name: string; ruleType: EvaluableRuleType; params: RuleParams; priority: string; status: string }[] = [
    {
      name: 'Large Cash Transaction', ruleType: 'LARGE_SINGLE_TRANSACTION',
      params: { transactionType: 'ANY', thresholdAmountKd: 5000 }, priority: 'HIGH', status: 'ACTIVE',
    },
    {
      name: 'Rapid Structuring Pattern', ruleType: 'VELOCITY_COUNT_SUM',
      params: { transactionType: 'CASH_DEPOSIT', windowHours: 72, minCount: 3, minAmountKd: 3000, maxAmountKd: 16000 },
      priority: 'CRITICAL', status: 'ACTIVE',
    },
    {
      name: 'High-Risk Jurisdiction Counterparty', ruleType: 'HIGH_RISK_COUNTRY',
      params: { includeGreylist: true, includeBlacklist: true }, priority: 'HIGH', status: 'ACTIVE',
    },
    {
      name: 'Large Wire Transfer (proposed)', ruleType: 'LARGE_SINGLE_TRANSACTION',
      params: { transactionType: 'WIRE_OUT', thresholdAmountKd: 20000 }, priority: 'MEDIUM', status: 'DRAFT',
    },
  ];

  const rules: { id: string; ruleType: EvaluableRuleType; params: RuleParams; priority: string }[] = [];
  for (const def of ruleDefs) {
    const createdAt = daysAgo(50);
    const rule = await prisma.screeningRule.create({
      data: {
        name: def.name, ruleType: def.ruleType, paramsJson: JSON.stringify(def.params),
        priority: def.priority, status: def.status, createdById: compliance.id, createdAt,
      },
    });
    await logAudit(prisma, {
      action: 'RULE_CREATED', actorId: compliance.id,
      details: { ruleId: rule.id, name: def.name, ruleType: def.ruleType }, createdAt,
    });
    if (def.status === 'ACTIVE') rules.push({ id: rule.id, ruleType: def.ruleType, params: def.params, priority: def.priority });
  }

  // ---------- transactions + emergent alerts (only for approved clients) ----------

  interface TxnPlan { type: TransactionType; amountKd: number; counterpartyCountry: string | null; daysAgo: number; hour: number }

  // Kuwait (KW) is itself FATF grey-listed in this app's seeded data, and
  // the transaction-monitoring HIGH_RISK_COUNTRY rule (unlike the onboarding
  // risk engine) has no domestic exemption — so a domestic counterparty
  // country must never be 'KW'. Cash/internal transactions have no
  // meaningful counterparty country at all (null); only cross-border wires
  // carry one, and only ever a genuinely clean jurisdiction ('AE'/'GB'/'US')
  // unless a scenario deliberately targets a grey/black-listed country.
  function plainHistory(seedOffset: number): TxnPlan[] {
    const types: TransactionType[] = ['CASH_DEPOSIT', 'CASH_WITHDRAWAL', 'WIRE_IN', 'WIRE_OUT', 'INTERNAL_TRANSFER'];
    const wireCountries = ['AE', 'GB', 'US'];
    const plans: TxnPlan[] = [];
    for (let i = 0; i < 7; i++) {
      const type = types[(i + seedOffset) % types.length];
      const isWire = type === 'WIRE_IN' || type === 'WIRE_OUT';
      plans.push({
        type,
        amountKd: 150 + ((i * 137 + seedOffset * 53) % 2600),
        counterpartyCountry: isWire ? wireCountries[(i + seedOffset) % wireCountries.length] : null,
        daysAgo: 3 + i * 4,
        hour: 9 + (i % 6),
      });
    }
    return plans;
  }

  const storyPlans: Record<string, TxnPlan[]> = {
    'Hind Al-Sabah': [
      { type: 'CASH_DEPOSIT', amountKd: 900, counterpartyCountry: null, daysAgo: 26, hour: 10 },
      { type: 'WIRE_IN', amountKd: 2200, counterpartyCountry: 'GB', daysAgo: 18, hour: 11 },
      // Large wire to a FATF blacklist jurisdiction — trips both large-transaction and high-risk-country rules.
      { type: 'WIRE_OUT', amountKd: 12000, counterpartyCountry: 'IR', daysAgo: 6, hour: 14 },
    ],
    'Khalid Al-Mutairi': [
      { type: 'WIRE_IN', amountKd: 1800, counterpartyCountry: 'AE', daysAgo: 24, hour: 9 },
      { type: 'CASH_WITHDRAWAL', amountKd: 700, counterpartyCountry: null, daysAgo: 20, hour: 13 },
      // Classic structuring: three cash deposits just under the large-txn threshold, within 48h.
      { type: 'CASH_DEPOSIT', amountKd: 3200, counterpartyCountry: null, daysAgo: 5, hour: 9 },
      { type: 'CASH_DEPOSIT', amountKd: 3600, counterpartyCountry: null, daysAgo: 4, hour: 15 },
      { type: 'CASH_DEPOSIT', amountKd: 3900, counterpartyCountry: null, daysAgo: 3, hour: 11 },
    ],
    'Al-Waha Real Estate Development': [
      { type: 'WIRE_IN', amountKd: 4200, counterpartyCountry: 'AE', daysAgo: 22, hour: 10 },
      { type: 'INTERNAL_TRANSFER', amountKd: 1500, counterpartyCountry: null, daysAgo: 15, hour: 12 },
      // Large legitimate real-estate settlement — will still trip the large-transaction rule.
      { type: 'WIRE_IN', amountKd: 8000, counterpartyCountry: 'AE', daysAgo: 7, hour: 10 },
    ],
    'Al-Noor Investment Holding': [
      { type: 'WIRE_IN', amountKd: 5200, counterpartyCountry: 'GB', daysAgo: 20, hour: 9 },
      { type: 'INTERNAL_TRANSFER', amountKd: 2100, counterpartyCountry: null, daysAgo: 16, hour: 10 },
      // Structuring cluster + one leg to a grey-list jurisdiction.
      { type: 'CASH_DEPOSIT', amountKd: 3500, counterpartyCountry: null, daysAgo: 9, hour: 9 },
      { type: 'CASH_DEPOSIT', amountKd: 4000, counterpartyCountry: null, daysAgo: 8, hour: 14 },
      { type: 'CASH_DEPOSIT', amountKd: 3800, counterpartyCountry: 'LB', daysAgo: 8, hour: 20 },
      { type: 'WIRE_OUT', amountKd: 9000, counterpartyCountry: 'AE', daysAgo: 2, hour: 11 },
    ],
    'Ahmed Al-Sabah': [
      { type: 'CASH_DEPOSIT', amountKd: 600, counterpartyCountry: null, daysAgo: 30, hour: 9 },
      { type: 'WIRE_IN', amountKd: 1900, counterpartyCountry: 'AE', daysAgo: 21, hour: 10 },
      // One incidental large deposit just over threshold — realistic, unactioned false-positive-shaped alert.
      { type: 'CASH_DEPOSIT', amountKd: 5500, counterpartyCountry: null, daysAgo: 10, hour: 9 },
    ],
  };

  interface EmergedAlert {
    id: string; severity: string; alertType: string; kycCaseId: string; caseName: string;
  }
  const emergedAlerts: EmergedAlert[] = [];

  for (const c of approvedCases) {
    const plans = storyPlans[c.nameEn] ?? plainHistory(approvedCases.indexOf(c));
    const chronological = [...plans].sort((a, b) => b.daysAgo - a.daysAgo);
    const priorTxns: TxnLike[] = [];

    for (const plan of chronological) {
      const createdAt = daysAgo(plan.daysAgo, plan.hour);
      const txnRef = await nextTxnRef(prisma);
      const txnLike: TxnLike = { type: plan.type, amountKd: plan.amountKd, counterpartyCountry: plan.counterpartyCountry, createdAt };

      let matchedAny = false;
      const matches: { rule: (typeof rules)[number]; result: ReturnType<typeof evaluateRule> }[] = [];
      for (const rule of rules) {
        const result = evaluateRule(rule.ruleType, rule.params, {
          transaction: txnLike, priorTransactions: priorTxns, fatfByCode,
        });
        if (result.matched) {
          matchedAny = true;
          matches.push({ rule, result });
        }
      }

      const txn = await prisma.transaction.create({
        data: {
          caseId: c.id, txnRef, type: plan.type, amountKd: plan.amountKd,
          counterpartyCountry: plan.counterpartyCountry, counterpartyName: null,
          status: matchedAny ? 'UNDER_REVIEW' : 'SAFE', enteredById: employee.id, createdAt,
        },
      });
      await logAudit(prisma, {
        action: 'TRANSACTION_RECORDED', caseId: c.id, actorId: employee.id,
        details: { txnRef, amountKd: plan.amountKd, type: plan.type, alertCount: matches.length }, createdAt,
      });

      for (const m of matches) {
        const alertType = DEFAULT_ALERT_TYPE[m.rule.ruleType];
        const alert = await prisma.alert.create({
          data: {
            transactionId: txn.id, ruleId: m.rule.id, severity: m.rule.priority,
            alertType, createdAt: hoursAfter(createdAt, 1),
          },
        });
        await logAudit(prisma, {
          action: 'ALERT_CREATED', caseId: c.id, actorId: employee.id,
          details: { ruleId: m.rule.id, transactionId: txn.id, txnRef }, createdAt: hoursAfter(createdAt, 1),
        });
        emergedAlerts.push({ id: alert.id, severity: m.rule.priority, alertType, kycCaseId: c.id, caseName: c.nameEn });
      }

      priorTxns.unshift(txnLike);
    }
  }

  // ---------- work a subset of alerts: resolve some, escalate some to investigations ----------

  const findByCase = (name: string) => emergedAlerts.filter((a) => a.kycCaseId === approvedCases.find((c) => c.nameEn === name)?.id);

  const investigations: { id: string; caseRef: string; kycCaseId: string; status: string }[] = [];

  // Ahmed Al-Sabah — incidental large-txn alert, left OPEN (unactioned, awaiting review).
  // (no action — stays OPEN by default)

  // Al-Waha — large-txn alert on a legitimate settlement: escalate, investigation stays NEW.
  for (const a of findByCase('Al-Waha Real Estate Development')) {
    const caseRef = await nextInvestigationRef(prisma);
    const createdAt = daysAgo(4);
    const inv = await prisma.investigationCase.create({
      data: { caseRef, alertId: a.id, kycCaseId: a.kycCaseId, status: 'NEW', openedById: compliance.id, createdAt },
    });
    await prisma.alert.update({ where: { id: a.id }, data: { status: 'IN_REVIEW' } });
    await logAudit(prisma, {
      action: 'ALERT_ESCALATED', caseId: a.kycCaseId, actorId: compliance.id,
      details: { alertId: a.id, investigationId: inv.id, caseRef }, createdAt,
    });
    investigations.push({ id: inv.id, caseRef, kycCaseId: a.kycCaseId, status: 'NEW' });
  }

  // Khalid Al-Mutairi — structuring alert: escalate, investigate, then close as a confirmed false positive.
  for (const a of findByCase('Khalid Al-Mutairi').filter((x) => x.alertType === 'STRUCTURING')) {
    const caseRef = await nextInvestigationRef(prisma);
    const openedAt = daysAgo(3);
    const inv = await prisma.investigationCase.create({
      data: { caseRef, alertId: a.id, kycCaseId: a.kycCaseId, status: 'INVESTIGATING', openedById: compliance.id, createdAt: openedAt },
    });
    await prisma.alert.update({ where: { id: a.id }, data: { status: 'IN_REVIEW' } });
    await logAudit(prisma, {
      action: 'ALERT_ESCALATED', caseId: a.kycCaseId, actorId: compliance.id,
      details: { alertId: a.id, investigationId: inv.id, caseRef }, createdAt: openedAt,
    });
    const closedAt = daysAgo(1);
    await prisma.investigationCase.update({
      where: { id: inv.id },
      data: {
        status: 'CLOSED', closedById: compliance.id, closedAt,
        findings: 'Client provided invoices confirming the three cash deposits were sequential inventory-purchase settlements from separate suppliers. No structuring intent found — classified as a false positive.',
      },
    });
    await prisma.alert.update({ where: { id: a.id }, data: { status: 'DISMISSED', resolvedById: compliance.id, resolvedAt: closedAt, notes: 'Confirmed legitimate — see closed investigation.' } });
    await logAudit(prisma, {
      action: 'INVESTIGATION_STATUS_CHANGED', caseId: a.kycCaseId, actorId: compliance.id,
      details: { investigationId: inv.id, from: 'INVESTIGATING', to: 'CLOSED' }, createdAt: closedAt,
    });
    investigations.push({ id: inv.id, caseRef, kycCaseId: a.kycCaseId, status: 'CLOSED' });
  }

  // Al-Noor Investment Holding — structuring alert: escalate, actively investigating.
  for (const a of findByCase('Al-Noor Investment Holding').filter((x) => x.alertType === 'STRUCTURING')) {
    const caseRef = await nextInvestigationRef(prisma);
    const createdAt = daysAgo(7);
    const inv = await prisma.investigationCase.create({
      data: {
        caseRef, alertId: a.id, kycCaseId: a.kycCaseId, status: 'INVESTIGATING', openedById: compliance.id, createdAt,
        findings: 'Reviewing three large cash deposits inconsistent with the entity\'s declared investment-holding activities. Source-of-funds documentation requested from the client.',
      },
    });
    await prisma.alert.update({ where: { id: a.id }, data: { status: 'IN_REVIEW' } });
    await logAudit(prisma, {
      action: 'ALERT_ESCALATED', caseId: a.kycCaseId, actorId: compliance.id,
      details: { alertId: a.id, investigationId: inv.id, caseRef }, createdAt,
    });
    investigations.push({ id: inv.id, caseRef, kycCaseId: a.kycCaseId, status: 'INVESTIGATING' });
  }

  // Hind Al-Sabah — high-risk-jurisdiction alert on the blacklist wire: escalate, ready for STR.
  for (const a of findByCase('Hind Al-Sabah').filter((x) => x.alertType === 'HIGH_RISK_JURISDICTION')) {
    const caseRef = await nextInvestigationRef(prisma);
    const createdAt = daysAgo(5);
    const inv = await prisma.investigationCase.create({
      data: {
        caseRef, alertId: a.id, kycCaseId: a.kycCaseId, status: 'AWAITING_APPROVAL', openedById: compliance.id, createdAt,
        findings: 'PEP client wired KD 12,000 to a FATF-blacklisted jurisdiction. Findings documented and an STR has been prepared; awaiting senior management sign-off before filing.',
      },
    });
    await prisma.alert.update({ where: { id: a.id }, data: { status: 'IN_REVIEW' } });
    await logAudit(prisma, {
      action: 'ALERT_ESCALATED', caseId: a.kycCaseId, actorId: compliance.id,
      details: { alertId: a.id, investigationId: inv.id, caseRef }, createdAt,
    });
    investigations.push({ id: inv.id, caseRef, kycCaseId: a.kycCaseId, status: 'AWAITING_APPROVAL' });
  }
  // Dismiss the duplicate large-transaction alert on the same Hind Al-Sabah wire.
  for (const a of findByCase('Hind Al-Sabah').filter((x) => x.alertType === 'LARGE_TRANSACTION')) {
    const resolvedAt = daysAgo(5);
    await prisma.alert.update({
      where: { id: a.id },
      data: { status: 'DISMISSED', resolvedById: compliance.id, resolvedAt, notes: 'Duplicate — see escalated high-risk-jurisdiction alert on the same transaction.' },
    });
    await logAudit(prisma, {
      action: 'ALERT_STATUS_CHANGED', caseId: a.kycCaseId, actorId: compliance.id,
      details: { alertId: a.id, from: 'OPEN', to: 'DISMISSED' }, createdAt: resolvedAt,
    });
  }

  // ---------- STR reports ----------

  const alNoorInv = investigations.find((i) => i.kycCaseId === approvedCases.find((c) => c.nameEn === 'Al-Noor Investment Holding')?.id);
  const hindInv = investigations.find((i) => i.kycCaseId === approvedCases.find((c) => c.nameEn === 'Hind Al-Sabah')?.id);

  if (alNoorInv) {
    const createdAt = daysAgo(6);
    const str = await prisma.strReport.create({
      data: {
        reportRef: await nextStrRef(prisma), kycCaseId: alNoorInv.kycCaseId, investigationCaseId: alNoorInv.id,
        status: 'UNDER_REVIEW', preparedById: compliance.id, createdAt,
        narrative: 'Client (an investment holding company) made three cash deposits of KD 3,500, KD 4,000 and KD 3,800 within a 48-hour window, structured to remain below the large single-transaction threshold. Pattern is inconsistent with the entity\'s declared investment-holding activity. Source-of-funds documentation has been requested and is pending.',
      },
    });
    await logAudit(prisma, { action: 'STR_CREATED', caseId: alNoorInv.kycCaseId, actorId: compliance.id, details: { reportRef: str.reportRef }, createdAt });
  }

  if (hindInv) {
    const createdAt = daysAgo(4);
    const submittedAt = daysAgo(1);
    const str = await prisma.strReport.create({
      data: {
        reportRef: await nextStrRef(prisma), kycCaseId: hindInv.kycCaseId, investigationCaseId: hindInv.id,
        status: 'SUBMITTED', preparedById: compliance.id, createdAt, submittedAt,
        narrative: 'Politically exposed client wired KD 12,000 to a FATF-blacklisted jurisdiction (Iran), materially inconsistent with prior transaction history. Reviewed and approved by senior management; filed with the FIU.',
      },
    });
    await logAudit(prisma, { action: 'STR_CREATED', caseId: hindInv.kycCaseId, actorId: compliance.id, details: { reportRef: str.reportRef }, createdAt });
    await logAudit(prisma, { action: 'STR_STATUS_CHANGED', caseId: hindInv.kycCaseId, actorId: manager.id, details: { reportRef: str.reportRef, from: 'UNDER_REVIEW', to: 'SUBMITTED' }, createdAt: submittedAt });
  }

  // Standalone STRs against two still-pending high-risk cases.
  const rezaCase = await prisma.kycCase.findFirst({ where: { profile: { fullName: 'Reza Karimi' } } });
  if (rezaCase) {
    const createdAt = daysAgo(2);
    const str = await prisma.strReport.create({
      data: {
        reportRef: await nextStrRef(prisma), kycCaseId: rezaCase.id, status: 'IN_PREPARATION',
        preparedById: compliance.id, createdAt,
        narrative: null,
      },
    });
    await logAudit(prisma, { action: 'STR_CREATED', caseId: rezaCase.id, actorId: compliance.id, details: { reportRef: str.reportRef }, createdAt });
  }

  const salimCase = await prisma.kycCase.findFirst({ where: { profile: { fullName: 'Salim Bin Rashid' } } });
  if (salimCase) {
    const createdAt = daysAgo(19);
    const submittedAt = daysAgo(17);
    const str = await prisma.strReport.create({
      data: {
        reportRef: await nextStrRef(prisma), kycCaseId: salimCase.id, status: 'SUBMITTED',
        preparedById: compliance.id, createdAt, submittedAt,
        narrative: 'Client\'s nationality and residency profile carry a FATF grey-list exposure alongside a related-party control link. Filed proactively pending onboarding decision.',
      },
    });
    await logAudit(prisma, { action: 'STR_CREATED', caseId: salimCase.id, actorId: compliance.id, details: { reportRef: str.reportRef }, createdAt });
    await logAudit(prisma, { action: 'STR_STATUS_CHANGED', caseId: salimCase.id, actorId: compliance.id, details: { reportRef: str.reportRef, from: 'IN_PREPARATION', to: 'SUBMITTED' }, createdAt: submittedAt });
  }

  // ---------- CRA recalculation audit trail (aggregate, matches recalculateAllCra's own log shape) ----------
  const craAssessedCount = [...INDIVIDUALS, ...CORPORATES].filter((s) => s.status === 'APPROVED' && s.craEligible).length;
  const totalApproved = [...INDIVIDUALS, ...CORPORATES].filter((s) => s.status === 'APPROVED').length;
  await logAudit(prisma, {
    action: 'CRA_RECALCULATED', actorId: compliance.id,
    details: { assessedCount: craAssessedCount, totalApproved }, createdAt: daysAgo(15),
  });
}
